Here's a simple example of how you can create a hairstyle generator in JavaScript:

```
let hairstyles = [
  "Barr",
  "playfulAZY",
  "BreepingNoise",
  "dude",
  "Hereaisal_.Sur"
];

function generateHairstyle() {
  let randomIndex = Math.floor(Math.random() * hairstyles.length);
  return hairstyles[randomIndex];
}

console.log(generateHairstyle());
```

